(396074, 34097, 9690, '<td valign="top">good capture of action.  nicely done</td>', 'good capture of action.  nicely done', '2003-08-22 12:44:09.000000', NULL, 1),
(396075, 34344, 9690, '<td valign="top">Good job.  Great depth of field.  I too submitted a flower pic, and many are rating them low on purpose because they feel they are cliche.  Hope you arent facing the same problem</td>', 'Good job.  Great depth of field.  I too submitted a flower pic, and many are rating them low on purpose because they feel they are cliche.  Hope you arent facing the same problem', '2003-08-22 12:45:06.000000', NULL, 1);
