(396513, 33928, 10799, '<td valign="top">For this challenge, I would have liked to see more  of the hose.  It was hard to see without the title prompting.</td>', 'For this challenge, I would have liked to see more  of the hose.  It was hard to see without the title prompting.', '2003-08-22 17:50:09.000000', NULL, 1),
(396515, 33648, 10799, '<td valign="top">What is on the right side of this picture?  I see something gray and a smaller red object.  I am not sure this captures the idea of representing a season.</td>', 'What is on the right side of this picture?  I see something gray and a smaller red object.  I am not sure this captures the idea of representing a season.', '2003-08-22 17:52:36.000000', NULL, 1),
(396537, 34260, 10883, '<td valign="top">Beatiful texture, colors and composition! - 8</td>', 'Beatiful texture, colors and composition! - 8', '2003-08-22 18:21:51.000000', NULL, 1),
(396538, 33539, 10799, '<td valign="top">I am sure it takes a  lot of skill and perservernce to catch a hummingbird for the photo... I wish there was less backgournd noise.  A closer crop would have added to this photo.</td>', 'I am sure it takes a  lot of skill and perservernce to catch a hummingbird for the photo... I wish there was less backgournd noise.  A closer crop would have added to this photo.', '2003-08-22 18:23:46.000000', NULL, 1),
(396540, 33320, 7763, '<td valign="top">I think cropping out the knee at the bottom would improve this. My first thought was ''what is that?'' It immediately distracted me from the subjects face and the rest of the photo.</td>', 'I think cropping out the knee at the bottom would improve this. My first thought was ''what is that?'' It immediately distracted me from the subjects face and the rest of the photo.', '2003-08-22 18:24:04.000000', NULL, 1),
(396543, 34358, 7763, '<td valign="top">nice but I dont care for the border</td>', 'nice but I dont care for the border', '2003-08-22 18:28:35.000000', NULL, 1),
(396545, 34253, 10799, '<td valign="top">It is hard to know what season you are depicting. This could be any season.</td>', 'It is hard to know what season you are depicting. This could be any season.', '2003-08-22 18:30:38.000000', NULL, 1),
(396552, 34037, 6888, '<td valign="top">great candid shot, nice choice to use b/w</td>', 'great candid shot, nice choice to use b/w', '2003-08-22 18:40:19.000000', NULL, 1),
