(396561, 33379, 6888, '<td valign="top">meets the challenge well, post card perfect shot...colors composition, dof are all right on...well done</td>', 'meets the challenge well, post card perfect shot...colors composition, dof are all right on...well done', '2003-08-22 18:44:43.000000', NULL, 1),
