(396583, 34141, 6888, '<td valign="top">this is a pretty busy shot and the bee is not readily at the center of attention here, plus given the fact that it is not totally in focus really takes more away from this</td>', 'this is a pretty busy shot and the bee is not readily at the center of attention here, plus given the fact that it is not totally in focus really takes more away from this', '2003-08-22 18:58:57.000000', NULL, 1),
(396615, 34129, 3865, '<td valign="top">Personally I think there is a bit too much white frame on this one, apart from that, beautiful!</td>', 'Personally I think there is a bit too much white frame on this one, apart from that, beautiful!', '2003-08-22 19:26:15.000000', NULL, 1),
(396618, 34359, 7763, '<td valign="top">Just a beautiful photograph!</td>', 'Just a beautiful photograph!', '2003-08-22 19:28:15.000000', NULL, 1),
(396647, 33671, 8860, '<td valign="top">Great shot - although isn''t this outside the dates for the challenge? Very nice light and composition. [8]</td>', 'Great shot - although isn''t this outside the dates for the challenge? Very nice light and composition. [8]', '2003-08-22 19:42:27.000000', NULL, 1),
(396653, 33372, 8860, '<td valign="top">This is just slightly too skewed anti-clockwise. A great shot and idea. Superb. 8</td>', 'This is just slightly too skewed anti-clockwise. A great shot and idea. Superb. 8', '2003-08-22 19:45:25.000000', NULL, 1),
