(398205, 33584, 4494, '<td valign="top">Awsome macro.  It really fits the challenge also because it looks like he''s drinking water because it''s hot outside.  Great job cropping as well... there''s just the right amount of water in the shot, and the bee/wasp is positioned perfectly.  9.</td>', 'Awsome macro.  It really fits the challenge also because it looks like he''s drinking water because it''s hot outside.  Great job cropping as well... there''s just the right amount of water in the shot, and the bee/wasp is positioned perfectly.  9.', '2003-08-25 00:28:53.000000', NULL, 1),
(398211, 34278, 4494, '<td valign="top">You know what... the cropping is so cool in this shot.  It''s brilliant really.   Conveys the message perfectly.</td>', 'You know what... the cropping is so cool in this shot.  It''s brilliant really.   Conveys the message perfectly.', '2003-08-25 00:31:56.000000', NULL, 1),
