INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(398753, 34097, 2612, '<td valign="top">I am not sure if the overexposure was intentional, but I think it takes away from a photo with a LOT of potential. I think the little girl in the yellow suit adds a little bit of clutter... maybe shot again when she has moved to the left? I know it''s hard with candids, but keep shooting.</td>', 'I am not sure if the overexposure was intentional, but I think it takes away from a photo with a LOT of potential. I think the little girl in the yellow suit adds a little bit of clutter... maybe shot again when she has moved to the left? I know it''s hard with candids, but keep shooting.', '2003-08-25 14:07:27.000000', NULL, 1),
(398759, 33449, 2612, '<td valign="top">Too bad the jocky''s head got chopped off by the horse on the far left....</td>', 'Too bad the jocky''s head got chopped off by the horse on the far left....', '2003-08-25 14:20:12.000000', NULL, 1),
