(400053, 33671, 4008, '<td valign="top">taken within the challenge period ? can''t be. but that is one of the rules. Picture is o.k. nothing special, maybe a low standpoint would have been better.</td>', 'taken within the challenge period ? can''t be. but that is one of the rules. Picture is o.k. nothing special, maybe a low standpoint would have been better.', '2003-08-26 17:15:58.000000', NULL, 1),
(400054, 33779, 4008, '<td valign="top">should not have cut of the top flower, and the yellow on the left is unnecessary. Needs more carefull composition. Colors are great. A reflector might have highlighted the texture of the green more.</td>', 'should not have cut of the top flower, and the yellow on the left is unnecessary. Needs more carefull composition. Colors are great. A reflector might have highlighted the texture of the green more.', '2003-08-26 17:18:56.000000', NULL, 1),
