(400082, 33878, 3697, '<td valign="top">Very nicely done. The little guy in his car, going down the dirt path... really shows warm, lazy summer days. Good work.</td>', 'Very nicely done. The little guy in his car, going down the dirt path... really shows warm, lazy summer days. Good work.', '2003-08-26 18:15:45.000000', NULL, 1),
(400086, 34245, 3697, '<td valign="top">Doing this in one in infrared took a fairly plain, uninteresting scene and made it into something you spend some time looking at. :) nice work.</td>', 'Doing this in one in infrared took a fairly plain, uninteresting scene and made it into something you spend some time looking at. :) nice work.', '2003-08-26 18:18:22.000000', NULL, 1),
