(400436, 34330, 6870, '<td valign="top">Real leaves, fake color, LOL. But they really do get that color! In the print version, I''ve eliminated all that noise.</td>', 'Real leaves, fake color, LOL. But they really do get that color! In the print version, I''ve eliminated all that noise.', '2003-08-27 01:27:31.000000', NULL, 0),
(400443, 34392, 10084, '<td valign="top">3 people likes the wall and 3 doesn''t. Wall or no wall that''s the question ?<br/><br/><i>Message edited by author 2003-08-27 00:40:29.</i></td>', '3 people likes the wall and 3 doesn''t. Wall or no wall that''s the question ?', '2003-08-27 01:29:46.000000', '2003-08-27 01:40:29.000000', 0),
