(400480, 33610, 9893, '<td valign="top">Beautiful shot - Go Powershot 70s! <br/>I see you resized it. Remember bigger is better ;)</td>', 'Beautiful shot - Go Powershot 70s! I see you resized it. Remember bigger is better ;)', '2003-08-27 01:39:04.000000', NULL, 0),
(400486, 34046, 6870, '<td valign="top">A wonderful sunset shot. It really sticks out as being excellent. Congrats on your first ribbon!</td>', 'A wonderful sunset shot. It really sticks out as being excellent. Congrats on your first ribbon!', '2003-08-27 01:41:25.000000', NULL, 0),
(400492, 33584, 10263, '<td valign="top">Way to go! Outstanding shot</td>', 'Way to go! Outstanding shot', '2003-08-27 01:42:01.000000', NULL, 0),
(400493, 34260, 6870, '<td valign="top">Oh yeah. Very nice. Super work!</td>', 'Oh yeah. Very nice. Super work!', '2003-08-27 01:42:03.000000', NULL, 0),
(400495, 34244, 9893, '<td valign="top">Beautiful image - great repitition &amp; use of line.</td>', 'Beautiful image - great repitition & use of line.', '2003-08-27 01:42:38.000000', NULL, 0),
(400498, 34041, 9854, '<td valign="top">Hello. For this, I gave you a 5. The picture has pleasing lines that seem to draw a "z" across the field. However, the exposure is a bit too much, creating a very harsh blown-out effect on the majority of the pic. It also needs a little more color saturation - or if you prefer, just desaturate all together and just make it a nice sepia or b/w. Finally, there''s a need to sharpen it up a bit to create more interest in the overall texture of the composition. Good to see you here in DPC!</td>', 'Hello. For this, I gave you a 5. The picture has pleasing lines that seem to draw a "z" across the field. However, the exposure is a bit too much, creating a very harsh blown-out effect on the majority of the pic. It also needs a little more color saturation - or if you prefer, just desaturate all together and just make it a nice sepia or b/w. Finally, there''s a need to sharpen it up a bit to create more interest in the overall texture of the composition. Good to see you here in DPC!', '2003-08-27 01:43:45.000000', NULL, 0),
(400501, 34392, 7711, '<td valign="top">I like the wall, just crop off the bottom inch of it or so! :)</td>', 'I like the wall, just crop off the bottom inch of it or so! :)', '2003-08-27 01:43:51.000000', NULL, 0),
(400502, 33841, 6870, '<td valign="top">Hey Edwin! Super work here! You can be both dramatic and gentle with your photos. This was my favorite for the challenge. I''m glad to see that it did well, but wish it had done even better. It''s sooooo nice!</td>', 'Hey Edwin! Super work here! You can be both dramatic and gentle with your photos. This was my favorite for the challenge. I''m glad to see that it did well, but wish it had done even better. It''s sooooo nice!', '2003-08-27 01:44:11.000000', NULL, 0),
(400503, 34046, 10263, '<td valign="top">Congrats on the ribbon. Gorgeous sky and great shot</td>', 'Congrats on the ribbon. Gorgeous sky and great shot', '2003-08-27 01:44:24.000000', NULL, 0),
