(400805, 34046, 8274, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by langdon:</b></div><hr/><i>Wowsa.  Beautiful image.  My only complaint is that it seems distorted.. though that''s mostly the effect the sand meeting the water has on my eyes.</i></td></tr></table> <br/> <br/>Thanks,  this is due to the 28mm equivalent wide angle of the Nikon 5400</td>', 'Originally posted by langdon:Wowsa.  Beautiful image.  My only complaint is that it seems distorted.. though that''s mostly the effect the sand meeting the water has on my eyes.  Thanks,  this is due to the 28mm equivalent wide angle of the Nikon 5400', '2003-08-27 06:57:27.000000', NULL, 0),
(400806, 34046, 8274, '<td valign="top">Thanks to all who voted, I am very humbled.</td>', 'Thanks to all who voted, I am very humbled.', '2003-08-27 06:58:11.000000', NULL, 0),
(400810, 34046, 8274, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by indigo997:</b></div><hr/><i>very beautiful. i have to bump this one up. love the color. what a great shot to hang in a beach house (if only i had one). not the best representation of a season though... the beach is empty so is this winter? it could also be any other season if you find the right spot. anyway, i love that sky. 7</i></td></tr></table> <br/> <br/>Yes! it is definately winter here in Australia at present. The beach is deserted as it was about 60F.</td>', 'Originally posted by indigo997:very beautiful. i have to bump this one up. love the color. what a great shot to hang in a beach house (if only i had one). not the best representation of a season though... the beach is empty so is this winter? it could also be any other season if you find the right spot. anyway, i love that sky. 7  Yes! it is definately winter here in Australia at present. The beach is deserted as it was about 60F.', '2003-08-27 07:17:22.000000', NULL, 0),
(400811, 33621, 4411, '<td valign="top">Lovely shot. Really brings back memories &amp; feelings of, as you say, lying on the grass and staring at the sky on a hot summers day. I can almost hear the birds singing : )</td>', 'Lovely shot. Really brings back memories & feelings of, as you say, lying on the grass and staring at the sky on a hot summers day. I can almost hear the birds singing : )', '2003-08-27 07:18:03.000000', NULL, 0),
(400816, 33283, 10546, '<td valign="top">Thanks for voting my photograph.<br/> <br/>First of all, yes I know I would get rammed for not following the challenge theme, but sometimes one also takes pictures for ourselves. <br/>I created this shot because I liked the original idea and was very happy with the final result. After carefull thinking decided to post it because it seemed like a photo to share with others even if I had no blue ribbon photo to submit.<br/> <br/>I will do this kind of "off-topic" again, but feel that adding "off-topic" to the title (the only part visible during voting) would be unfair as it might seem like I''m trying to get away with it.<br/> <br/>Also, couldn''t decide on a fair criteria for marking comments as helpfull so in the end, decided to marked them all. I will try and address this puzzle later.<br/> <br/>RichT8496 and everyone else: Thanks for the support. Went back and took a look at your "Fork and Spade" and I see what you mean. My first idea was "Springtime" and you can imagine where that was leading me... I just couldn''t find a nice source for 1000 springs.<br/> <br/>============================<br/> <br/>In Portugal "Fall"/"Autumn" is "Outono" so the pun only works in american english.</td>', 'Thanks for voting my photograph. First of all, yes I know I would get rammed for not following the challenge theme, but sometimes one also takes pictures for ourselves. I created this shot because I liked the original idea and was very happy with the final result. After carefull thinking decided to post it because it seemed like a photo to share with others even if I had no blue ribbon photo to submit. I will do this kind of "off-topic" again, but feel that adding "off-topic" to the title (the only part visible during voting) would be unfair as it might seem like I''m trying to get away with it. Also, couldn''t decide on a fair criteria for marking comments as helpfull so in the end, decided to marked them all. I will try and address this puzzle later. RichT8496 and everyone else: Thanks for the support. Went back and took a look at your "Fork and Spade" and I see what you mean. My first idea was "Springtime" and you can imagine where that was leading me... I just couldn''t find a nice source for 1000 springs. ============================ In Portugal "Fall"/"Autumn" is "Outono" so the pun only works in american english.', '2003-08-27 07:31:36.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(400831, 34090, 10546, '<td valign="top">Hello Anabela,<br/> <br/>Nice picture from Sweden. I find the habit of having nude manequins exposed during sales very disturbing (its problably just me...) and just realized that it happens everywhere not just here.<br/> <br/>pottersclay75 and Anabela: The polarizer sugestion was a very valid one. Don''t know if the final result would convey the "window shop" look, only experimenting would tell. Sometimes a filter can make all the difference and that''s why my next camera must be able to use filters.</td>', 'Hello Anabela, Nice picture from Sweden. I find the habit of having nude manequins exposed during sales very disturbing (its problably just me...) and just realized that it happens everywhere not just here. pottersclay75 and Anabela: The polarizer sugestion was a very valid one. Don''t know if the final result would convey the "window shop" look, only experimenting would tell. Sometimes a filter can make all the difference and that''s why my next camera must be able to use filters.', '2003-08-27 08:06:08.000000', NULL, 0),
(400837, 33379, 10342, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by e301:</b></div><hr/><i>You seem to have caught a great quality of light here - there''s a real natural feeling to it that many people struggle to get. The artefacts and pixelation are a bit of a nightmare though - especially on the distant details. What happened? A real shame.</i></td></tr></table> <br/> <br/>This was my first submission, and to meet the guidelines, I messed up the picture... in its original form its a crystal clear, no jaggies 2272x1704 picture.... next time I hope I don''t mess up<br/> <br/></td>', 'Originally posted by e301:You seem to have caught a great quality of light here - there''s a real natural feeling to it that many people struggle to get. The artefacts and pixelation are a bit of a nightmare though - especially on the distant details. What happened? A real shame.  This was my first submission, and to meet the guidelines, I messed up the picture... in its original form its a crystal clear, no jaggies 2272x1704 picture.... next time I hope I don''t mess up ', '2003-08-27 08:15:38.000000', NULL, 0),
(400838, 33379, 10342, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Olyuzi:</b></div><hr/><i>Lovely composition and beautiful colors.  This picture has a painterly quality to it.  Hard to tell if the palm trees and buildings are out of focus or a PS filter was applied. Doesn''t matter, I find this image exceptional, however you achieved it.</i></td></tr></table> <br/> <br/>Actually, I just squated and took a picture from low off the ground... no filters, but in meeting the size guidlines I messed the picture up... it really is crystal clear in its original form</td>', 'Originally posted by Olyuzi:Lovely composition and beautiful colors.  This picture has a painterly quality to it.  Hard to tell if the palm trees and buildings are out of focus or a PS filter was applied. Doesn''t matter, I find this image exceptional, however you achieved it.  Actually, I just squated and took a picture from low off the ground... no filters, but in meeting the size guidlines I messed the picture up... it really is crystal clear in its original form', '2003-08-27 08:17:54.000000', NULL, 0),
(400839, 33379, 10342, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by faidoi:</b></div><hr/><i>Composition is incredible. See some jaggies, but because the composition is so good. A "10"</i></td></tr></table> <br/> <br/>Thanks for your comments... in meeting the size guidlines I messed the picture up, and the jaggies appeared... it really is a better picture in it original form</td>', 'Originally posted by faidoi:Composition is incredible. See some jaggies, but because the composition is so good. A "10"  Thanks for your comments... in meeting the size guidlines I messed the picture up, and the jaggies appeared... it really is a better picture in it original form', '2003-08-27 08:20:00.000000', NULL, 0),
(400841, 33379, 10342, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by scw1217:</b></div><hr/><i>An unusual cityscape point of view, but it works well for you.  Nice composition.</i></td></tr></table> <br/> <br/>This and other pictures that day were made at Lake Eola in Orlando, Florida... I wish I had not messed up the picture in submitting it...in meeting the size guidlines I caused jaggie...it really is crystal clear in its original form</td>', 'Originally posted by scw1217:An unusual cityscape point of view, but it works well for you.  Nice composition.  This and other pictures that day were made at Lake Eola in Orlando, Florida... I wish I had not messed up the picture in submitting it...in meeting the size guidlines I caused jaggie...it really is crystal clear in its original form', '2003-08-27 08:23:13.000000', NULL, 0),
